MATURITY_DESCRIPTIONS_EN = {key: TEXTS["en"][f"maturity_desc_{key}"] for key in MATURITY_KEYS}


def problems() -> list[str]:
    """Missing or extra keys between the languages (used by the tests)."""
    out = []
    reference = set(TEXTS["en"])
    for code in LANGUAGES:
        if set(TEXTS.get(code, {})) != reference:
            out.append(f"{code}: keys differ from en: {sorted(set(TEXTS.get(code, {})) ^ reference)}")
    return out
